import {FreeCamera} from './free-camera.js';
import * as THREE from './vendor/three.module.js';import {OrbitControls} from './vendor/OrbitControls.js';
export class BuildViewer{constructor(host,onPick){this.host=host;this.scene=new THREE.Scene();this.scene.background=new THREE.Color('#282b2d');this.renderer=new THREE.WebGLRenderer({antialias:true});this.renderer.setPixelRatio(Math.min(devicePixelRatio,2));host.append(this.renderer.domElement);this.camera=new THREE.PerspectiveCamera(40,1,.1,2500);this.controls=new OrbitControls(this.camera,this.renderer.domElement);this.controls.enableDamping=true;this.controls.minDistance=2;this.controls.maxDistance=1500;this.scene.add(new THREE.HemisphereLight(0xffffff,0x9ca4ad,2.1));const light=new THREE.DirectionalLight(0xffffff,2);light.position.set(-50,100,150);this.scene.add(light);this.root=new THREE.Group();this.scene.add(this.root);this.tex=new Map();this.geo=new THREE.BoxGeometry(1,1,1);this.ray=new THREE.Raycaster();this.free=new FreeCamera(this.renderer.domElement,this.camera,()=>{},()=>document.getElementById('cameraMode').click());this.lastTime=performance.now();this.renderer.domElement.onpointerdown=e=>this.down=[e.clientX,e.clientY];this.renderer.domElement.addEventListener('pointerup',e=>{if(!this.down||Math.hypot(e.clientX-this.down[0],e.clientY-this.down[1])>4)return;const r=this.renderer.domElement.getBoundingClientRect();this.ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),this.camera);const hit=this.ray.intersectObjects(this.root.children)[0];if(hit?.instanceId!==undefined)onPick(hit.object.userData.indices[hit.instanceId])});new ResizeObserver(()=>this.resize()).observe(host);this.renderer.setAnimationLoop(()=>{if(!host.offsetWidth)return;const now=performance.now();this.free.update((now-this.lastTime)/1000);this.lastTime=now;if(!this.free.active)this.controls.update();this.renderer.render(this.scene,this.camera)})}resize(){const w=this.host.clientWidth,h=this.host.clientHeight;if(!w||!h)return;this.renderer.setSize(w,h);this.camera.aspect=w/h;this.camera.updateProjectionMatrix()}setFree(active){this.free.setActive(active);this.controls.enabled=!active;if(!active){const direction=new THREE.Vector3();this.camera.getWorldDirection(direction);this.controls.target.copy(this.camera.position).addScaledVector(direction,Math.max(this.p?.width||10,10));this.controls.update()}}setProject(p){this.p=p;this.free.speed=Math.max(8,Math.max(p.width,p.height)*.3);for(const m of [...this.root.children]){this.root.remove(m);m.material.dispose()}if(this.floor){this.scene.remove(this.floor);this.floor.geometry.dispose();this.floor.material.dispose()}const groups=new Map();p.cells.forEach((b,i)=>{if(b>=0){if(!groups.has(b))groups.set(b,[]);groups.get(b).push(i)}});const dummy=new THREE.Object3D();for(const [idx,indices]of groups){const b=p.palette[idx];let texture=this.tex.get(b.texture);if(!texture){texture=new THREE.TextureLoader().load(b.texture);texture.magFilter=THREE.NearestFilter;texture.minFilter=THREE.NearestFilter;texture.colorSpace=THREE.SRGBColorSpace;this.tex.set(b.texture,texture)}const mesh=new THREE.InstancedMesh(this.geo,new THREE.MeshLambertMaterial({map:texture}),indices.length);mesh.userData.indices=indices;indices.forEach((i,k)=>{dummy.position.set(i%p.width-(p.width-1)/2,p.height-1-Math.floor(i/p.width)+.5,0);dummy.updateMatrix();mesh.setMatrixAt(k,dummy.matrix)});mesh.instanceMatrix.needsUpdate=true;mesh.computeBoundingSphere();this.root.add(mesh)}const size=Math.max(p.width,p.height)*2;this.floor=new THREE.GridHelper(size,Math.min(size,128),0x35445b,0x202e41);this.floor.position.y=-.02;this.scene.add(this.floor);this.reset()}reset(){if(!this.p)return;const size=Math.max(this.p.width,this.p.height);this.controls.target.set(0,this.p.height/2,0);this.camera.position.set(size*.58,this.p.height/2+size*.24,size*1.65);this.controls.update();this.resize()}front(){if(!this.p)return;const size=Math.max(this.p.width/Math.max(.4,this.camera.aspect),this.p.height);this.camera.position.set(0,this.p.height/2,size*1.5);this.controls.target.set(0,this.p.height/2,0);this.controls.update()}}
